<?php
function desktop_layout_defaults(){return [
    'slogan'=>'每天，持续更新！','show_version'=>true,'banners'=>[],
    'home_tabs'=>desktop_home_tabs_defaults(),
    'game_info'=>desktop_game_info_defaults(),
    'forum_filters'=>[['key'=>'all','label'=>'全部'],['key'=>'digest','label'=>'精华'],['key'=>'sticky','label'=>'置顶']],
    'pagination_mode'=>'paged','games_forum_id'=>2,'collect_enabled'=>false,'feedback_link'=>'','forum_stats'=>['forums_count'=>0,'today_posts'=>0],
    'layout_labels'=>['home'=>'首页推荐','forums'=>'游戏板块','search'=>'帖子搜索','notifications'=>'消息中心','profile'=>'用户中心','medals'=>'勋章中心','tasks'=>'任务中心','settings'=>'设置','thread'=>'帖子详情','explore'=>'探索','mine'=>'我的','all'=>'查看全部 →','banner_action'=>'查看详情','search_placeholder'=>'搜索帖子 / 游戏资源…']
];}
function desktop_layout_validate($c){
    if(!is_string($c['slogan'])||strlen($c['slogan'])>300||!is_bool($c['show_version'])||!is_bool($c['collect_enabled'])||!in_array($c['pagination_mode'],['paged','infinite'],true)||!desktop_external_url($c['feedback_link']))desktop_config_error('页面布局配置不正确。');
    $c['game_info']=desktop_game_info_validate($c['game_info']);
    $c['games_forum_id']=max(0,(int)$c['games_forum_id']);
    if(!is_array($c['banners'])||count($c['banners'])>20)desktop_config_error('轮播最多 20 条。');$ids=[];
    foreach($c['banners'] as &$b){if(!is_array($b))desktop_config_error('轮播格式不正确。');$b=array_replace(['id'=>'','image'=>'','title'=>'','slogan'=>'','link_type'=>'thread','link'=>'','button_text'=>'查看详情','enabled'=>true],$b);
        foreach(['id','image','title','slogan','link','button_text'] as $k)if(!is_string($b[$k])||strlen($b[$k])>2048)desktop_config_error('轮播字段不正确。');
        if(!preg_match('/^[a-zA-Z0-9_-]{1,80}$/',$b['id'])||isset($ids[$b['id']])||!desktop_external_url($b['image'])||!is_bool($b['enabled'])||!in_array($b['link_type'],['thread','external'],true)||($b['link_type']==='thread'&&!preg_match('/^[1-9]\d*$/',$b['link']))||($b['link_type']==='external'&&!desktop_external_url($b['link'])))desktop_config_error('轮播 ID、图片或跳转不正确。');$ids[$b['id']]=true;
    }unset($b);
    foreach(['home_tabs'=>['latest','hot','digest','games'],'forum_filters'=>['all','digest','sticky']] as $key=>$allowed){if(!is_array($c[$key])||count($c[$key])>8)desktop_config_error('筛选标签不正确。');$seen=[];foreach($c[$key] as $tab){if(!is_array($tab)||!in_array($tab['key'] ?? '',$allowed,true)||isset($seen[$tab['key']])||!is_string($tab['label'] ?? null)||strlen($tab['label'])>100)desktop_config_error('筛选标签重复或格式不正确。');$seen[$tab['key']]=true;}}
    $c['home_tabs']=desktop_home_tabs_normalize($c['home_tabs'],$c['games_forum_id']);
    if(!is_array($c['layout_labels']))desktop_config_error('布局文案格式不正确。');foreach($c['layout_labels'] as $text)if(!is_string($text)||strlen($text)>200)desktop_config_error('布局文案过长。');return $c;
}
function desktop_forum_stats(){try{$p=get_pdo();$midnight=(new DateTime('today',new DateTimeZone('Asia/Shanghai')))->getTimestamp();return ['forums_count'=>(int)$p->query('SELECT COUNT(*) FROM '.table('forum_forum')." f WHERE f.status IN (1,3) AND f.type IN ('forum','sub') AND (f.posts>0 OR f.todayposts>0 OR EXISTS(SELECT 1 FROM ".table('forum_thread')." t WHERE t.fid=f.fid AND t.displayorder>=0))")->fetchColumn(),'today_posts'=>(int)$p->query('SELECT COUNT(*) FROM '.table('forum_post')." WHERE invisible=0 AND dateline>=".$midnight)->fetchColumn()];}catch(Throwable $e){return ['forums_count'=>0,'today_posts'=>0];}}

function desktop_home_tabs_defaults($games=2){$out=[];foreach(['latest'=>'最新推荐','hot'=>'热门回复','digest'=>'精华帖','games'=>'游戏资源'] as $key=>$label)$out[]=['key'=>$key,'label'=>$label,'enabled'=>true,'icon'=>'','sort'=>$key==='hot'?'replies':'lastpost','view'=>'newreply','orderby'=>$key==='hot'?'replies':'','filter'=>$key==='digest'?'digest':'','forum_ids'=>$key==='games'?[$games]:[],'count'=>30,'link'=>''];return $out;}
function desktop_home_tabs_normalize($tabs,$games=2){$defaults=array_column(desktop_home_tabs_defaults($games),null,'key');$out=[];foreach($tabs as $tab){$d=$defaults[$tab['key']];$tab=array_replace($d,$tab);if(!is_bool($tab['enabled'])||!in_array($tab['sort'],['lastpost','dateline','replies'],true)||!is_string($tab['icon'])||strlen($tab['icon'])>80||!is_int($tab['count'])||$tab['count']<1||$tab['count']>50||!is_array($tab['forum_ids'])||count($tab['forum_ids'])>100||!is_string($tab['link'])||!desktop_external_url($tab['link']))desktop_config_error('首页板块配置不正确：条数为 1–50，来源为版块 ID 数组。');foreach($tab['forum_ids'] as $fid)if(!is_int($fid)||$fid<1)desktop_config_error('来源版块 ID 必须是正整数。');$tab['forum_ids']=array_values(array_unique($tab['forum_ids']));$tab['view']=$tab['sort']==='dateline'?'newthread':'newreply';$tab['orderby']=$tab['sort']==='replies'?'replies':'';if(!in_array($tab['filter'],['','digest','sticky'],true))desktop_config_error('首页过滤条件错误。');$out[]=$tab;}return $out;}

function desktop_game_info_defaults(){static $value=null;if($value!==null)return $value;$labels=json_decode(file_get_contents(__DIR__.'/content_labels.json'),true) ?: [];$fields=[];foreach(['game_name','english_name','game_type','developer','publisher','official_site','release_date','netdisk'] as $key)$fields[]=['key'=>$key,'label'=>$labels[$key] ?? '资源信息','enabled'=>true];return $value=['enabled'=>true,'title'=>'游戏信息','empty_text'=>'本帖未设置分类信息。','fields'=>$fields];}
function desktop_game_info_validate($value){if(!is_array($value))desktop_config_error('游戏信息配置格式不正确。');$value=array_replace(desktop_game_info_defaults(),$value);if(!is_bool($value['enabled'])||!is_string($value['title'])||strlen($value['title'])>180||!is_string($value['empty_text'])||strlen($value['empty_text'])>1000||!is_array($value['fields'])||count($value['fields'])>64)desktop_config_error('游戏信息标题、占位或字段配置不正确。');$seen=[];$out=[];foreach($value['fields'] as $field){if(!is_array($field)||!is_string($field['key'] ?? null)||!preg_match('/^[a-zA-Z][a-zA-Z0-9_]{0,63}$/',$field['key'])||isset($seen[$field['key']])||!is_string($field['label'] ?? null)||strlen($field['label'])>180||!is_bool($field['enabled'] ?? null))desktop_config_error('游戏信息字段标识重复或格式不正确。');$seen[$field['key']]=true;$out[]=['key'=>$field['key'],'label'=>$field['label'],'enabled'=>$field['enabled']];}$value['fields']=$out;return $value;}
